  child = spawn("/usr/bin/sandbox-exec", ["-p", sandbox, ...command], {
    cwd: spec.cwd!,
    env: message.context
      ? {
          DOTLN_RESIDENT_STORE: message.context.residentStore,
          DOTLN_RESIDENT_EPISODE_ID: message.context.episodeId,
        }
      : {},
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
  });
