      .map((path) => `(allow file-read-data (subpath ${quote(path)}))`)
      .join("") +
    `(allow file-read-data (literal "/") (literal "/dev/null") (literal "/dev/urandom"))(allow file-write* (subpath ${quote(root)}) (literal "/dev/null"))`
