  "codex-cli-exec": {
    row: "X-U1",
    label: "observed",
    reason: "detached parent, stored CLI authentication; lifetime unknown",
  },
} as const;
export interface CliLaunchClaims {
  transport: CliTransport;
  row: string;
  profileId: string;
  model: string;
  effort: string;
  harnessVersion: string;
  origin: "actor";
  episodeId: string;
}
export interface CliActorObservation {
  launch: CliLaunchClaims;
  result?: WorkerResult | WriterResult;
  failure?: string;
}
export function assertCliActorSpec(
  value: unknown,
): asserts value is CliActorSpec {
  const v = value as CliActorSpec;
  if (
    !v ||
    typeof v !== "object" ||
    Array.isArray(v) ||
    Object.keys(v).some((k) => !["transport", "request"].includes(k)) ||
    !Object.hasOwn(DETACHED_LAUNCH_ROWS, v.transport) ||
    !v.request
  )
    throw new Error("invalid CLI actor declaration");
  if (isWriterRequest(v.request)) validateWriterRequest(v.request);
  else validateRequest(v.request);
}
export function cliActorRequest(spec: CliActorSpec, episodeId: string) {
  return { ...spec.request, episodeId };
}
export function assertCliObservation(
  value: unknown,
  spec: CliActorSpec,
  episodeId: string,
): asserts value is CliActorObservation {
  const v = value as CliActorObservation;
  const launch = v?.launch;
  if (
    !v ||
    !launch ||
    Object.keys(v).some((k) => !["launch", "result", "failure"].includes(k)) ||
    Object.keys(launch).some(
      (k) =>
        ![
          "transport",
          "row",
          "profileId",
          "model",
          "effort",
          "harnessVersion",
          "origin",
          "episodeId",
        ].includes(k),
    ) ||
    launch.transport !== spec.transport ||
    launch.row !== DETACHED_LAUNCH_ROWS[spec.transport].row ||
    launch.profileId !== spec.request.profile.profileId ||
    launch.model !== spec.request.model ||
    launch.effort !== spec.request.effort ||
    launch.origin !== "actor" ||
    launch.episodeId !== episodeId ||
    typeof launch.harnessVersion !== "string" ||
    !launch.harnessVersion ||
    (v.result === undefined) === (v.failure === undefined)
  )
    throw new Error("invalid CLI actor observation");
  if (
    v.failure !== undefined &&
    ![
      "model-unavailable",
      "transport-failed",
      "interrupted",
      "invalid-result",
      "deadline-exceeded",
      "output-limit",
      "profile-refused",
      "supervisor-lost",
    ].includes(v.failure)
  )
    throw new Error("invalid CLI failure code");
  const request = cliActorRequest(spec, episodeId);
  if (v.result !== undefined) {
    if (isWriterRequest(request)) parseStoredWriterResult(v.result, request);
    else parseWorkerResult(v.result, request);
  }
}

import { fork } from "node:child_process";
import { fileURLToPath } from "node:url";
import type { ActorAdapter, ActorResult, ActorSpec } from "./actor-contract.js";
import { assertActorSpec } from "./actor-contract.js";
import {
  DETACHED_LAUNCH_ROWS,
  cliActorRequest,
  type CliActorSpec,
  type CliLaunchClaims,
} from "./cli-actor-contract.js";
import { WorkerFailure } from "./worker-protocol.js";
import {
  ClaudeCliPrintWorkOrderTransport,
  CodexCliExecWorkOrderTransport,
  runWorkerProcess,
  type ProcessRunner,
} from "./worker-transport.js";

export interface CliActorContext {
  residentStore: string;
  episodeId: string;
}
const emptyDigest =
  "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
export const actorFailure = (reason: string): ActorResult => ({
  exitCode: null,
  signal: null,
  stdoutSha256: emptyDigest,
  firstLine: "",
  verified: false,
  reason,
});
function claims(
  spec: CliActorSpec,
  context: CliActorContext,
  harnessVersion: string,
): CliLaunchClaims {
  return {
    transport: spec.transport,
    row: DETACHED_LAUNCH_ROWS[spec.transport].row,
    profileId: spec.request.profile.profileId,
    model: spec.request.model,
    effort: spec.request.effort,
    harnessVersion,
    origin: "actor",
    episodeId: context.episodeId,
  };
}
/** Used by the disposable supervisor in production and by process doubles. */
export function startCliEpisode(
  spec: CliActorSpec,
  context: CliActorContext,
  runner: ProcessRunner = runWorkerProcess,
  version?: string,
) {
  const stamped: ProcessRunner = (launch) =>
    runner({
      ...launch,
      resident: { store: context.residentStore, episodeId: context.episodeId },
    });
  const transport =
    spec.transport === "claude-cli-print"
      ? new ClaudeCliPrintWorkOrderTransport(stamped, version)
      : new CodexCliExecWorkOrderTransport(stamped, version);
  const launch = claims(spec, context, transport.harnessVersion);
  const failed = (error: unknown): ActorResult => ({
    ...actorFailure("worker-failed"),
    worker: {
      launch,
      failure: error instanceof WorkerFailure ? error.code : "transport-failed",
    },
  });
  try {
    const dispatched = transport.dispatch(
      cliActorRequest(spec, context.episodeId),
      Date.now,
    );
    return {
      kill: dispatched.kill,
      completed: Promise.all([dispatched.receipt, dispatched.completed]).then(
        ([, result]): ActorResult => ({
          ...actorFailure("worker-result"),
          exitCode: 0,
          worker: { launch, result },
        }),
        failed,
      ),
    };
  } catch (error) {
    return { kill: () => {}, completed: Promise.resolve(failed(error)) };
  }
}
export function cliWorkerAdapter(
  options: {
    rows?: Readonly<
      Record<string, { row: string; label: string; reason: string }>
    >;
    runner?: ProcessRunner;
    version?: string;
  } = {},
): ActorAdapter {
  const rows = options.rows ?? DETACHED_LAUNCH_ROWS;
  return {
    kind: "cli-worker",
    available(spec?: ActorSpec) {
      if (!spec?.worker) return "cli-worker needs a declared request";
      const row = rows[spec.worker.transport];
      return row?.label === "observed"
        ? null
        : `${row?.row ?? DETACHED_LAUNCH_ROWS[spec.worker.transport].row}: ${row?.label ?? "unavailable"}; ${row?.reason ?? "detached launch row missing"}`;
    },
    run(spec, context) {
      assertActorSpec(spec);
      if (!context || !spec.worker)
        throw new Error("CLI actor requires resident context");
      const unavailable = this.available(spec);
      if (unavailable) throw new Error(unavailable);
      if (options.runner)
        return startCliEpisode(
          spec.worker,
          context,
          options.runner,
          options.version,
        );
      const child = fork(
        fileURLToPath(new URL("./cli-episode.js", import.meta.url)),
        [],
        {
          execArgv: [],
          stdio: ["ignore", "ignore", "ignore", "ipc"],
        },
      );
      let observed: ActorResult | undefined;
      const completed = new Promise<ActorResult>((resolve) => {
        child.on("message", (value) => {
          observed = value as ActorResult;
        });
        child.on("error", () => {});
        child.on("close", () =>
          resolve(
            observed ?? {
              ...actorFailure("worker-failed"),
              worker: {
                launch: claims(spec.worker!, context, "unknown"),
                failure: "supervisor-lost",
              },
            },
          ),
        );
      });
      child.send({ spec: spec.worker, context });
      return {
        completed,
        kill: () => {
          if (child.connected) child.send({ kill: true });
        },
      };
    },
  };
}

// The supervising process owns the detached CLI group. Resident death closes
// IPC and kills that group; the next resident records the unobserved episode lost.
import { startCliEpisode, type CliActorContext } from "./cli-actor.js";
import { assertCliActorSpec, type CliActorSpec } from "./cli-actor-contract.js";
let active: ReturnType<typeof startCliEpisode> | undefined;
process.on("disconnect", () => {
  if (active) active.kill();
  else process.exit(1);
});
process.on(
  "message",
  (message: {
    kill?: boolean;
    spec: CliActorSpec;
    context: CliActorContext;
  }) => {
    if (message.kill) {
      active?.kill();
      return;
    }
    if (active) return;
    assertCliActorSpec(message.spec);
    active = startCliEpisode(message.spec, message.context);
    void active.completed.then((result) => {
      if (process.connected)
        process.send!(result, () => {
          process.disconnect();
          process.exit(0);
        });
      else process.exit(0);
    });
  },
);

/** Human decisions are durable inputs, never model completions. */
export interface HandoffQuestion {
  workOrderId: string;
  question: string;
  options: { id: string; label: string }[];
  evidenceRefs: string[];
}
export interface HandoffPacket extends HandoffQuestion {
  episodeId: string;
}
const text = (v: unknown, max: number): v is string =>
  typeof v === "string" &&
  v.trim().length > 0 &&
  v.length <= max &&
  !/[\u0000-\u001f\u007f]/u.test(v);
export function assertHandoffQuestion(
  value: unknown,
): asserts value is HandoffQuestion {
  const v = value as HandoffQuestion;
  if (
    !v ||
    typeof v !== "object" ||
    Array.isArray(v) ||
    Object.keys(v).some(
      (k) =>
        ![
          "workOrderId",
          "question",
          "options",
          "evidenceRefs",
          "episodeId",
        ].includes(k),
    ) ||
    !text(v.workOrderId, 256) ||
    !text(v.question, 2000) ||
    !Array.isArray(v.options) ||
    v.options.length < 2 ||
    v.options.length > 10 ||
    v.options.some(
      (o) =>
        !o ||
        typeof o !== "object" ||
        Object.keys(o).some((k) => !["id", "label"].includes(k)) ||
        !text(o.id, 100) ||
        !text(o.label, 1000),
    ) ||
    new Set(v.options.map((o) => o.id)).size !== v.options.length ||
    !Array.isArray(v.evidenceRefs) ||
    !v.evidenceRefs.length ||
    v.evidenceRefs.length > 100 ||
    v.evidenceRefs.some((ref) => !text(ref, 1000))
  )
    throw new Error("invalid human handoff question");
}
export function assertHandoffPacket(
  value: unknown,
): asserts value is HandoffPacket {
  assertHandoffQuestion(value);
  if (
    !("episodeId" in value) ||
    typeof value.episodeId !== "string" ||
    !/^[a-zA-Z0-9_-]+$/u.test(value.episodeId)
  )
    throw new Error("invalid human handoff episode");
}

import {
  closeSync,
  fsyncSync,
  mkdirSync,
  openSync,
  readFileSync,
  realpathSync,
  writeFileSync,
  linkSync,
  unlinkSync,
} from "node:fs";
import { randomUUID } from "node:crypto";
import { join } from "node:path";
import { canonicalStringify } from "@dotln/compiler";
import { assertActorSpec, type ActorAdapter } from "./actor-contract.js";
import { assertHandoffPacket } from "./handoff-contract.js";
import { actorFailure } from "./cli-actor.js";

export const humanHandoffAdapter: ActorAdapter = {
  kind: "human-handoff",
  available: () => null,
  run(spec, context) {
    assertActorSpec(spec);
    if (!context || !spec.handoff)
      throw new Error("handoff requires resident context");
    const packet = { ...spec.handoff, episodeId: context.episodeId };
    assertHandoffPacket(packet);
    const directory = join(
      context.residentStore,
      "control",
      "local",
      "handoffs",
    );
    mkdirSync(directory, { recursive: true, mode: 0o700 });
    if (realpathSync(directory) !== directory)
      throw new Error("handoff directory must be canonical and not symlinked");
    const path = join(directory, `${packet.episodeId}.json`);
    const content = canonicalStringify(packet) + "\n";
    const temporary = join(
      directory,
      `.${packet.episodeId}.${randomUUID()}.tmp`,
    );
    const fd = openSync(temporary, "wx", 0o600);
    try {
      try {
        writeFileSync(fd, content);
        fsyncSync(fd);
      } finally {
        closeSync(fd);
      }
      try {
        linkSync(temporary, path);
      } catch (error) {
        if (
          (error as NodeJS.ErrnoException).code !== "EEXIST" ||
          realpathSync(path) !== path ||
          readFileSync(path, "utf8") !== content
        )
          throw error;
      }
      const directoryFd = openSync(directory, "r");
      try {
        fsyncSync(directoryFd);
      } finally {
        closeSync(directoryFd);
      }
    } finally {
      unlinkSync(temporary);
    }
    return {
      handoff: packet,
      completed: Promise.resolve(actorFailure("handoff-requested")),
      kill: () => {},
    };
  },
};

/** Pure, bounded discovery wire contract. Candidates carry observations, not authority. */
export const WORK_CANDIDATE_KINDS = [
  "failing-lint",
  "failing-test",
  "misplaced-file",
  "stale-generated",
  "repeated-repair",
] as const;
export interface WorkCandidate {
  candidateId: string;
  kind: (typeof WORK_CANDIDATE_KINDS)[number];
  paths: string[];
  evidence: string[];
  proposedHome?: string;
  /** Observed scope only; this is not a repair-effort estimate. */
  size: { files: number };
}
export interface DiscoveryEvidence {
  evidenceId: string;
  source: string;
  facts: Record<string, string | number | string[]>;
}
export interface DiscoveryReport {
  schemaVersion: 1;
  candidates: WorkCandidate[];
  evidence: DiscoveryEvidence[];
}
export function discoveryPath(value: unknown): asserts value is string {
  if (
    typeof value !== "string" ||
    value.length > 240 ||
    !value ||
    value.startsWith("/") ||
    /[\\\x00-\x1f:]/u.test(value) ||
    value
      .split("/")
      .some((part) => !part || part === "." || part === ".." || part === ".git")
  )
    throw new Error("discovery requires a bounded relative path");
}
function object(value: unknown, keys: string[]): Record<string, unknown> {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    Object.keys(value).some((key) => !keys.includes(key))
  )
    throw new Error("invalid discovery object");
  return value as Record<string, unknown>;
}
const text = (v: unknown): v is string =>
  typeof v === "string" &&
  v.length > 0 &&
  v.length <= 1024 &&
  !/[\x00-\x1f]/u.test(v);
function strings(v: unknown): asserts v is string[] {
  if (
    !Array.isArray(v) ||
    !v.length ||
    v.length > 128 ||
    !v.every(text) ||
    new Set(v).size !== v.length
  )
    throw new Error("invalid discovery string list");
}
export function decodeDiscoveryReport(value: unknown): DiscoveryReport {
  const root = object(value, ["schemaVersion", "candidates", "evidence"]);
  if (
    root.schemaVersion !== 1 ||
    !Array.isArray(root.candidates) ||
    root.candidates.length > 128 ||
    !Array.isArray(root.evidence) ||
    root.evidence.length > 256 ||
    JSON.stringify(value).length > 60000
  )
    throw new Error("invalid discovery report bounds");
  const ids = new Set<string>();
  for (const raw of root.evidence) {
    const row = object(raw, ["evidenceId", "source", "facts"]);
    if (!text(row.evidenceId) || ids.has(row.evidenceId) || !text(row.source))
      throw new Error("invalid discovery evidence");
    ids.add(row.evidenceId);
    if (
      !row.facts ||
      typeof row.facts !== "object" ||
      Array.isArray(row.facts) ||
      Object.keys(row.facts).length > 16
    )
      throw new Error("invalid discovery facts");
    for (const [key, fact] of Object.entries(row.facts)) {
      if (!text(key)) throw new Error("invalid discovery fact key");
      if (Array.isArray(fact)) strings(fact);
      else if (!(
        text(fact) ||
        (typeof fact === "number" && Number.isSafeInteger(fact) && fact >= 0)
      ))
        throw new Error("invalid discovery fact");
    }
  }
  const candidates = new Set<string>();
  for (const raw of root.candidates) {
    const row = object(raw, [
      "candidateId",
      "kind",
      "paths",
      "evidence",
      "proposedHome",
      "size",
    ]);
    if (
      !text(row.candidateId) ||
      candidates.has(row.candidateId) ||
      !WORK_CANDIDATE_KINDS.includes(row.kind as WorkCandidate["kind"])
    )
      throw new Error("invalid discovery candidate");
    candidates.add(row.candidateId);
    strings(row.paths);
    row.paths.forEach(discoveryPath);
    strings(row.evidence);
    if (row.evidence.some((id) => !ids.has(id)))
      throw new Error("unresolved discovery evidence");
    const size = object(row.size, ["files"]);
    if (size.files !== row.paths.length)
      throw new Error("candidate size differs from observed scope");
    if (row.kind === "misplaced-file") discoveryPath(row.proposedHome);
    else if (row.proposedHome !== undefined)
      throw new Error("unexpected proposed home");
  }
  return structuredClone(value) as DiscoveryReport;
}

/** SHA-256 of the canonical wire bytes, kept pure for deterministic log replay. */
export function discoveryOutputSha256(report: DiscoveryReport): string {
  const bytes = new TextEncoder().encode(JSON.stringify(report) + "\n");
  const padded = new Uint8Array(Math.ceil((bytes.length + 9) / 64) * 64);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const data = new DataView(padded.buffer);
  data.setUint32(padded.length - 4, bytes.length * 8);
  const h = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
    0x1f83d9ab, 0x5be0cd19,
  ];
  const k = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
    0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
    0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const rotate = (n: number, bits: number) => (n >>> bits) | (n << (32 - bits));
  const w = new Uint32Array(64);
  for (let offset = 0; offset < padded.length; offset += 64) {
    for (let i = 0; i < 16; i++) w[i] = data.getUint32(offset + i * 4);
    for (let i = 16; i < 64; i++) {
      const x = w[i - 15]!,
        y = w[i - 2]!;
      w[i] =
        w[i - 16]! +
        (rotate(x, 7) ^ rotate(x, 18) ^ (x >>> 3)) +
        w[i - 7]! +
        (rotate(y, 17) ^ rotate(y, 19) ^ (y >>> 10));
    }
    let [a, b, c, d, e, f, g, z] = h as [
      number,
      number,
      number,
      number,
      number,
      number,
      number,
      number,
    ];
    for (let i = 0; i < 64; i++) {
      const t1 =
        (z +
          (rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25)) +
          ((e & f) ^ (~e & g)) +
          k[i]! +
          w[i]!) >>>
        0;
      const t2 =
        ((rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22)) +
          ((a & b) ^ (a & c) ^ (b & c))) >>>
        0;
      z = g;
      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, z].forEach((value, i) => {
      h[i] = (h[i]! + value) >>> 0;
    });
  }
  return h.map((value) => value.toString(16).padStart(8, "0")).join("");
}

// Disposable supervisor: losing the resident's IPC connection kills the entire
// script process group, including on resident SIGKILL. It never opens a socket.
import { realpathSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { discoverySandbox } from "./discovery-sandbox.js";
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { StringDecoder } from "node:string_decoder";
import {
  decodeDiscoveryReport,
  type DiscoveryReport,
} from "./work-candidate.js";
import type { ActorSpec } from "./actor-catalog.js";
