});

import { realpathSync } from "node:fs";
import { dirname } from "node:path";
/** Native boundary shared by direct checks and the whole trusted producer episode. */
export function discoverySandbox(
  root: string,
  runtimeReads: readonly string[] = [],
): string {
  const quote = (path: string) => JSON.stringify(path);
  return (
    `(version 1)(allow default)(deny network*)(deny file-read-data)(deny file-write*)` +
    [
      root,
      "/usr",
      "/bin",
      "/System",
      "/Library/Apple",
      "/opt/homebrew",
      dirname(dirname(realpathSync(process.execPath))),
      "/private/var/db/dyld",
      ...runtimeReads,
    ]
      .map((path) => `(allow file-read-data (subpath ${quote(path)}))`)
      .join("") +
    `(allow file-read-data (literal "/") (literal "/dev/null") (literal "/dev/urandom"))(allow file-write* (subpath ${quote(root)}) (literal "/dev/null"))`
  );
}

/** Private supervisor entry: the entire process is already in discoverySandbox.
 * The public CLI always establishes its own boundary for each target command. */
import { discoverWithinActor } from "./discovery.js";
try {
  const [worktree, profilePath, ...extra] = process.argv.slice(2);
  if (!worktree || extra.length)
    throw new Error("invalid discovery actor invocation");
  process.stdout.write(
    JSON.stringify(
      discoverWithinActor(worktree, profilePath ? { profilePath } : {}),
    ) + "\n",
  );
} catch {
  process.stderr.write(
    "Discovery failed; inspect the bounded target configuration locally.\n",
  );
  process.exitCode = 1;
}

