    "checks",
    "placements",
    "generated",
    "repairHistory",
  ]);
  if (v.checks !== undefined) {
    const kinds = new Set();
    for (const raw of array(v.checks)) {
      const c = record(raw, ["kind", "argv", "paths"]);
      if (!["lint", "test"].includes(String(c.kind)) || kinds.has(c.kind))
        fail("duplicate or invalid check kind");
