        schemaVersion: 1,
        eventId: `result:${stage}`,
        type: "CommandResult",
        occurredAt: 0,
        actorId: "discovery",
        workstreamId: "discovery",
        payload: { commandId: `discovery.${stage}`, result: "completed" },
