      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, z].forEach((value, i) => {
      h[i] = (h[i]! + value) >>> 0;
